// ChorusOmnis API: Cloudflare Pages Function handling every /api/* request.
// Storage: one R2 bucket (binding BUCKET). index.json holds piece metadata,
// uploaded scores and MP3s live under pieces/<id>/...
// Reading is public. Changing anything needs the ADMIN_PASSWORD secret.

const VOICES = ["Tenor 1", "Tenor 2", "Baritone 1", "Baritone 2", "Bass 1", "Bass 2", "Other"];
const MAX_TRACKS = 12;
const MAX_BYTES = 90 * 1024 * 1024; // Pages Functions request limit is 100 MB
const CACHE = "public, max-age=31536000, immutable";

const json = (data, status = 200, extra = {}) =>
  new Response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json", "cache-control": "no-store", ...extra },
  });
const fail = (msg, status = 400) => json({ error: msg }, status);
const clean = (v, max) => String(v ?? "").trim().slice(0, max);
const newId = () => crypto.randomUUID().replace(/-/g, "").slice(0, 10);
const sortPieces = (list) => [...list].sort((a, b) => a.order - b.order || a.createdAt - b.createdAt);

function safeEqual(a, b) {
  const enc = new TextEncoder();
  const x = enc.encode(a), y = enc.encode(b);
  let d = x.length ^ y.length;
  for (let i = 0; i < Math.max(x.length, y.length); i++) d |= (x[i] || 0) ^ (y[i] || 0);
  return d === 0;
}
function authed(request, env) {
  const pw = env.ADMIN_PASSWORD || "";
  if (!pw) return false;
  const h = request.headers.get("Authorization") || "";
  return safeEqual(h.startsWith("Bearer ") ? h.slice(7) : "", pw);
}

async function readIndex(env) {
  const o = await env.BUCKET.get("index.json");
  return o ? JSON.parse(await o.text()) : { pieces: [] };
}
const writeIndex = (env, idx) =>
  env.BUCKET.put("index.json", JSON.stringify(idx), { httpMetadata: { contentType: "application/json" } });

async function readBody(request) {
  const len = Number(request.headers.get("content-length") || 0);
  if (len > MAX_BYTES) return { error: fail("File is too large (limit 90 MB)", 413) };
  const buf = await request.arrayBuffer();
  if (!buf.byteLength) return { error: fail("Empty file") };
  if (buf.byteLength > MAX_BYTES) return { error: fail("File is too large (limit 90 MB)", 413) };
  return { buf };
}

const starts = (u, ...bytes) => bytes.every((v, i) => u[i] === v);
function sniffScore(u) {
  if (starts(u, 0x25, 0x50, 0x44, 0x46)) return { type: "pdf", mime: "application/pdf" };
  if (starts(u, 0x89, 0x50, 0x4e, 0x47)) return { type: "png", mime: "image/png" };
  if (starts(u, 0xff, 0xd8, 0xff)) return { type: "jpg", mime: "image/jpeg" };
  if (starts(u, 0x52, 0x49, 0x46, 0x46) && u[8] === 0x57 && u[9] === 0x45 && u[10] === 0x42 && u[11] === 0x50)
    return { type: "webp", mime: "image/webp" };
  return null;
}
const isMp3 = (u) => starts(u, 0x49, 0x44, 0x33) || (u[0] === 0xff && (u[1] & 0xe0) === 0xe0);
const head = (buf) => new Uint8Array(buf, 0, Math.min(12, buf.byteLength));

// YouTube links: youtube.com/watch, youtu.be, /shorts, /embed, /live and playlists.
const YT_ERR = "That doesn't look like a YouTube video or playlist link";
function parseYouTube(raw) {
  raw = String(raw || "").trim();
  if (!raw) return null;
  let u;
  try { u = new URL(raw); } catch { try { u = new URL("https://" + raw); } catch { return null; } }
  const h = u.hostname.replace(/^www\./, "").replace(/^m\./, "");
  let id = null, list = u.searchParams.get("list");
  if (h === "youtu.be") id = u.pathname.slice(1).split("/")[0];
  else if (h === "youtube.com" || h === "music.youtube.com") {
    if (u.pathname === "/watch") id = u.searchParams.get("v");
    else { const m = u.pathname.match(/^\/(shorts|embed|live|v)\/([\w-]{11})/); if (m) id = m[2]; }
  } else return null;
  if (id && !/^[\w-]{11}$/.test(id)) id = null;
  if (list && !/^[\w-]{10,60}$/.test(list)) list = null;
  return id || list ? { id, list } : null;
}
function ytFrom(raw) {
  const y = parseYouTube(raw);
  if (!y) return null;
  const url = y.id ? `https://www.youtube.com/watch?v=${y.id}${y.list ? "&list=" + y.list : ""}` : `https://www.youtube.com/playlist?list=${y.list}`;
  return { vid: y.id, list: y.list, url };
}

// ---------- accounts, sessions, approval ----------
// Members live in R2 as users/<id>.json (id = first 32 hex chars of SHA-256 of the email).
// Sessions are signed cookies (HMAC keyed from ADMIN_PASSWORD). Changing ADMIN_PASSWORD signs everyone out.
const PBKDF2_ITER = 100000; // Workers' maximum. Lower it BEFORE anyone registers if you hit CPU-limit errors on the Free plan.
const MAX_USERS = 300;
const COOKIE = "co_session";
const DUMMY_SALT = "AAAAAAAAAAAAAAAAAAAAAA";
const enc = new TextEncoder();
const b64u = (buf) => btoa(String.fromCharCode(...new Uint8Array(buf))).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
const unb64u = (s) => Uint8Array.from(atob(s.replace(/-/g, "+").replace(/_/g, "/")), (c) => c.charCodeAt(0));
const hex = (buf) => [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
const sha256hex = async (s) => hex(await crypto.subtle.digest("SHA-256", enc.encode(s)));
const cookie = (value, maxAge) => `${COOKIE}=${value}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${maxAge}`;
function getCookie(request, name) {
  const m = (request.headers.get("cookie") || "").match(new RegExp("(?:^|;\\s*)" + name + "=([^;]+)"));
  return m ? m[1] : "";
}

async function hashPassword(pw, saltB64, iter) {
  const salt = saltB64 ? unb64u(saltB64) : crypto.getRandomValues(new Uint8Array(16));
  const key = await crypto.subtle.importKey("raw", enc.encode(pw), "PBKDF2", false, ["deriveBits"]);
  const bits = await crypto.subtle.deriveBits({ name: "PBKDF2", hash: "SHA-256", salt, iterations: iter }, key, 256);
  return { salt: b64u(salt), hash: b64u(bits) };
}
const hmacKey = (env) =>
  crypto.subtle.importKey("raw", enc.encode("chorusomnis-session:" + env.ADMIN_PASSWORD), { name: "HMAC", hash: "SHA-256" }, false, ["sign", "verify"]);
async function makeToken(env, payload) {
  const body = b64u(enc.encode(JSON.stringify(payload)));
  return body + "." + b64u(await crypto.subtle.sign("HMAC", await hmacKey(env), enc.encode(body)));
}
async function readToken(env, token) {
  const [body, sig] = String(token || "").split(".");
  if (!body || !sig) return null;
  try {
    if (!(await crypto.subtle.verify("HMAC", await hmacKey(env), unb64u(sig), enc.encode(body)))) return null;
    const p = JSON.parse(new TextDecoder().decode(unb64u(body)));
    return p.exp > Date.now() ? p : null;
  } catch { return null; }
}

async function readUser(env, id) {
  if (!/^[a-f0-9]{32}$/.test(String(id))) return null;
  const o = await env.BUCKET.get(`users/${id}.json`);
  return o ? JSON.parse(await o.text()) : null;
}
// create=true only succeeds if the user does not exist yet
const putUser = (env, u, create = false) =>
  env.BUCKET.put(`users/${u.id}.json`, JSON.stringify(u), {
    httpMetadata: { contentType: "application/json" },
    customMetadata: { status: u.status },
    ...(create ? { onlyIf: { etagDoesNotMatch: "*" } } : {}),
  });
async function listUsers(env) {
  const out = [];
  let cursor;
  do {
    const r = await env.BUCKET.list({ prefix: "users/", cursor, include: ["customMetadata"] });
    out.push(...r.objects);
    cursor = r.truncated ? r.cursor : undefined;
  } while (cursor);
  return out;
}

// lock an account / the admin login for 15 minutes after 8 wrong passwords
async function checkLock(env, key) {
  const o = await env.BUCKET.get(`lock/${key}.json`);
  if (!o) return false;
  return JSON.parse(await o.text()).until > Date.now();
}
async function recordFail(env, key) {
  const k = `lock/${key}.json`, o = await env.BUCKET.get(k);
  let d = o ? JSON.parse(await o.text()) : { fails: 0, until: 0, first: Date.now() };
  if (Date.now() - d.first > 15 * 60000) d = { fails: 0, until: 0, first: Date.now() };
  d.fails++;
  if (d.fails >= 8) d.until = Date.now() + 15 * 60000;
  await env.BUCKET.put(k, JSON.stringify(d));
}
const clearFails = (env, key) => env.BUCKET.delete(`lock/${key}.json`);

async function getSession(request, env) {
  const p = await readToken(env, getCookie(request, COOKIE));
  if (!p) return null;
  if (p.r === "a") return { role: "admin", name: "Admin" };
  const u = await readUser(env, p.u);
  if (!u || u.status !== "approved" || u.hash.slice(0, 10) !== p.pv) return null;
  return { role: "member", id: u.id, name: u.name };
}

async function register(request, env) {
  const b = await request.json().catch(() => ({}));
  if (b.website) return json({ ok: true, status: "pending" }, 201); // honeypot: bots fill this in
  const name = clean(b.name, 60), email = clean(b.email, 120).toLowerCase(), pw = String(b.password || "");
  if (name.length < 2) return fail("Please enter your full name");
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) return fail("Please enter a valid email address");
  if (pw.length < 8 || pw.length > 200) return fail("Password must be at least 8 characters");
  if ((await listUsers(env)).length >= MAX_USERS) return fail("Registration is full. Please contact the admin.", 403);
  const id = (await sha256hex(email)).slice(0, 32);
  const h = await hashPassword(pw, null, PBKDF2_ITER);
  const ok = await putUser(env, { id, name, email, salt: h.salt, hash: h.hash, iter: PBKDF2_ITER, status: "pending", createdAt: Date.now() }, true);
  if (!ok) return fail("That email is already registered. Try signing in.", 409);
  return json({ ok: true, status: "pending" }, 201);
}

async function memberLogin(request, env) {
  const b = await request.json().catch(() => ({}));
  const email = clean(b.email, 120).toLowerCase(), pw = String(b.password || "");
  if (!email || !pw) return fail("Enter your email and password");
  const id = (await sha256hex(email)).slice(0, 32), lockKey = "u-" + id;
  if (await checkLock(env, lockKey)) return fail("Too many attempts. Please wait 15 minutes and try again.", 429);
  const u = await readUser(env, id);
  const { hash } = await hashPassword(pw, u ? u.salt : DUMMY_SALT, u ? u.iter || 100000 : PBKDF2_ITER);
  if (!u || !safeEqual(hash, u.hash)) { await recordFail(env, lockKey); return fail("Wrong email or password", 401); }
  await clearFails(env, lockKey);
  if (u.status !== "approved")
    return json({ error: "Your account is waiting for admin approval. Please check back later.", pending: true }, 403);
  const token = await makeToken(env, { r: "m", u: u.id, pv: u.hash.slice(0, 10), exp: Date.now() + 30 * 864e5 });
  return json({ role: "member", name: u.name }, 200, { "set-cookie": cookie(token, 30 * 86400) });
}

async function adminLogin(request, env) {
  const b = await request.json().catch(() => ({}));
  if (await checkLock(env, "admin")) return fail("Too many attempts. Please wait 15 minutes and try again.", 429);
  if (!safeEqual(String(b.password || ""), env.ADMIN_PASSWORD)) { await recordFail(env, "admin"); return fail("Wrong password", 401); }
  await clearFails(env, "admin");
  const token = await makeToken(env, { r: "a", exp: Date.now() + 7 * 864e5 });
  return json({ role: "admin" }, 200, { "set-cookie": cookie(token, 7 * 86400) });
}

// ---------- private notes on scores ----------
// Stored per person: annotations/<member id or "admin">/<piece id>.json
// { scoreKey, pages: { "1": [ {t:"pen"|"hl", c, w, p:[x,y,...]} | {t:"txt", c, x, y, s, str} ] } }
// Coordinates are 0..1 of the page as shown without rotation.
const annKey = (uid, pieceId) => `annotations/${uid}/${pieceId}.json`;
function cleanItems(items) {
  if (!Array.isArray(items) || items.length > 2000) return null;
  const num = (v, lo, hi) => (typeof v === "number" && Number.isFinite(v) ? Math.min(hi, Math.max(lo, +v.toFixed(4))) : null);
  const out = [];
  for (const it of items) {
    if (!it || typeof it !== "object") return null;
    const c = /^#[0-9a-fA-F]{6}$/.test(it.c) ? it.c : "#111111";
    if (it.t === "pen" || it.t === "hl") {
      if (!Array.isArray(it.p) || it.p.length < 2 || it.p.length > 6000 || it.p.length % 2) return null;
      const p = it.p.map((v) => num(v, -0.2, 1.2));
      const w = num(it.w, 0.0005, 0.1);
      if (w === null || p.includes(null)) return null;
      out.push({ t: it.t, c, w, p });
    } else if (it.t === "txt") {
      const x = num(it.x, -0.2, 1.2), y = num(it.y, -0.2, 1.2), s = num(it.s, 0.005, 0.2);
      const str = String(it.str ?? "").slice(0, 200);
      if (x === null || y === null || s === null || !str) return null;
      out.push({ t: "txt", c, x, y, s, str });
    } else return null;
  }
  return out;
}
async function deleteAnnotations(env, { uid, pieceId }) {
  const keys = [];
  let cursor;
  do {
    const r = await env.BUCKET.list({ prefix: uid ? `annotations/${uid}/` : "annotations/", cursor });
    for (const o of r.objects) if (!pieceId || o.key.endsWith(`/${pieceId}.json`)) keys.push(o.key);
    cursor = r.truncated ? r.cursor : undefined;
  } while (cursor);
  for (let i = 0; i < keys.length; i += 500) await env.BUCKET.delete(keys.slice(i, i + 500));
}

async function serveFile(request, env, key) {
  if (!key.startsWith("pieces/") || key.split("/").includes("..")) return fail("Not found", 404);
  const obj = await env.BUCKET.get(key, { range: request.headers });
  if (!obj) return fail("Not found", 404);
  const h = new Headers();
  obj.writeHttpMetadata(h);
  h.set("etag", obj.httpEtag);
  h.set("cache-control", "private, max-age=3600");
  h.set("vary", "Cookie");
  h.set("accept-ranges", "bytes");
  h.set("x-content-type-options", "nosniff");
  let status = 200;
  if (obj.range && request.headers.has("range")) {
    let o = obj.range.offset ?? 0, l = obj.range.length ?? obj.size - o;
    if (obj.range.suffix !== undefined) { l = Math.min(obj.range.suffix, obj.size); o = obj.size - l; }
    h.set("content-range", `bytes ${o}-${o + l - 1}/${obj.size}`);
    h.set("content-length", String(l));
    status = 206;
  } else {
    h.set("content-length", String(obj.size));
  }
  return new Response(request.method === "HEAD" ? null : obj.body, { status, headers: h });
}

async function onRequest({ request, env }) {
  if (!env.BUCKET) return fail("R2 binding BUCKET is missing. See README.", 500);
  const url = new URL(request.url);
  const seg = url.pathname.split("/").filter(Boolean).slice(1).map((s) => {
    try { return decodeURIComponent(s); } catch { return s; }
  });
  const method = request.method;

  try {
    if (!env.ADMIN_PASSWORD) return fail("ADMIN_PASSWORD is not set. See README.", 500);
    if (method !== "GET" && method !== "HEAD") {
      const origin = request.headers.get("origin");
      if (origin && origin !== url.origin) return fail("Cross-site request blocked", 403);
    }
    const sess = await getSession(request, env);

    // ---- open to everyone: who am I, register, sign in, sign out
    if (seg[0] === "me" && method === "GET") {
      if (!sess) return json({ role: null });
      const out = { role: sess.role, name: sess.name };
      if (sess.role === "admin") out.pending = (await listUsers(env)).filter((o) => o.customMetadata?.status === "pending").length;
      return json(out);
    }
    if (seg[0] === "register" && method === "POST") return register(request, env);
    if (seg[0] === "login" && method === "POST") return memberLogin(request, env);
    if (seg[0] === "admin-login" && method === "POST") return adminLogin(request, env);
    if (seg[0] === "logout" && method === "POST") return json({ ok: true }, 200, { "set-cookie": cookie("", 0) });

    // ---- approved members and the admin can read
    if (!sess) return fail("Please sign in", 401);
    if (seg[0] === "files" && (method === "GET" || method === "HEAD"))
      return serveFile(request, env, seg.slice(1).join("/"));
    if (seg[0] === "pieces" && seg.length === 1 && method === "GET") {
      const idx = await readIndex(env);
      return json(sortPieces(idx.pieces));
    }

    // ---- private notes: each member (and the admin) only ever sees their own
    if (seg[0] === "annotations" && /^[a-f0-9]{10}$/.test(seg[1] || "")) {
      const key = annKey(sess.role === "admin" ? "admin" : sess.id, seg[1]);
      if (seg.length === 2 && method === "GET") {
        const o = await env.BUCKET.get(key);
        return json(o ? JSON.parse(await o.text()) : { scoreKey: null, pages: {} });
      }
      if (seg.length === 3 && method === "PUT") {
        const page = Number(seg[2]);
        if (!Number.isInteger(page) || page < 1 || page > 2000) return fail("Bad page number");
        if (Number(request.headers.get("content-length") || 0) > 600000) return fail("Too many notes on one page", 413);
        const b = await request.json().catch(() => ({}));
        const items = cleanItems(b.items);
        if (!items) return fail("Invalid notes");
        const idx = await readIndex(env);
        const piece = idx.pieces.find((p) => p.id === seg[1]);
        if (!piece) return fail("Piece not found", 404);
        if (!piece.score || piece.score.key !== b.scoreKey) return fail("This score was replaced, so notes cannot be saved to it", 409);
        const o = await env.BUCKET.get(key);
        let doc = o ? JSON.parse(await o.text()) : null;
        if (!doc || doc.scoreKey !== b.scoreKey) doc = { scoreKey: b.scoreKey, pages: {} };
        if (items.length) doc.pages[page] = items; else delete doc.pages[page];
        doc.updatedAt = Date.now();
        const text = JSON.stringify(doc);
        if (text.length > 1500000) return fail("Too many notes on this score", 413);
        await env.BUCKET.put(key, text, { httpMetadata: { contentType: "application/json" } });
        return json({ ok: true });
      }
      return fail("Not found", 404);
    }

    // ---- everything below is admin only
    if (sess.role !== "admin") return fail("Admin only", 403);

    // member approval
    if (seg[0] === "members") {
      if (seg.length === 1 && method === "GET") {
        const objs = await listUsers(env);
        const texts = await Promise.all(objs.map((o) => env.BUCKET.get(o.key).then((x) => (x ? x.text() : null))));
        const users = texts.filter(Boolean).map((t) => {
          const u = JSON.parse(t);
          return { id: u.id, name: u.name, email: u.email, status: u.status, createdAt: u.createdAt };
        });
        users.sort((x, y) => (x.status === "pending" ? 0 : 1) - (y.status === "pending" ? 0 : 1) || x.name.localeCompare(y.name));
        return json(users);
      }
      const u = await readUser(env, seg[1]);
      if (!u) return fail("Member not found", 404);
      if (seg[2] === "approve" && seg.length === 3 && method === "POST") {
        u.status = "approved"; u.approvedAt = Date.now();
        await putUser(env, u);
        return json({ ok: true });
      }
      if (seg.length === 2 && method === "DELETE") {
        await env.BUCKET.delete(`users/${u.id}.json`);
        await deleteAnnotations(env, { uid: u.id });
        return json({ ok: true });
      }
      if (seg.length === 2 && method === "PATCH") {
        const b = await request.json().catch(() => ({}));
        const pw = String(b.password || "");
        if (pw.length < 8 || pw.length > 200) return fail("Password must be at least 8 characters");
        const h = await hashPassword(pw, null, PBKDF2_ITER);
        u.salt = h.salt; u.hash = h.hash; u.iter = PBKDF2_ITER;
        await putUser(env, u);
        await clearFails(env, "u-" + u.id);
        return json({ ok: true });
      }
      return fail("Not found", 404);
    }
    if (seg[0] !== "pieces") return fail("Not found", 404);

    const idx = await readIndex(env);

    // create piece
    if (seg.length === 1 && method === "POST") {
      const b = await request.json().catch(() => ({}));
      const title = clean(b.title, 120);
      if (!title) return fail("Title is required");
      const piece = {
        id: newId(),
        group: clean(b.group, 60) || "Songs",
        part: clean(b.part, 60),
        title,
        sub: clean(b.sub, 120),
        order: idx.pieces.reduce((m, p) => Math.max(m, p.order), 0) + 1,
        score: null,
        tracks: [],
        yt: null,
        createdAt: Date.now(),
      };
      idx.pieces.push(piece);
      await writeIndex(env, idx);
      return json(piece, 201);
    }

    // reorder
    if (seg[1] === "reorder" && seg.length === 2 && method === "POST") {
      const b = await request.json().catch(() => ({}));
      const ids = Array.isArray(b.ids) ? b.ids : [];
      const rank = new Map(ids.map((id, i) => [id, i]));
      sortPieces(idx.pieces).forEach((p, i) => (p.order = rank.has(p.id) ? rank.get(p.id) : ids.length + i));
      await writeIndex(env, idx);
      return json({ ok: true });
    }

    const piece = idx.pieces.find((p) => p.id === seg[1]);
    if (!piece) return fail("Piece not found", 404);

    // edit / delete piece
    if (seg.length === 2 && method === "PATCH") {
      const b = await request.json().catch(() => ({}));
      if ("title" in b) { const t = clean(b.title, 120); if (!t) return fail("Title is required"); piece.title = t; }
      if ("part" in b) piece.part = clean(b.part, 60);
      if ("sub" in b) piece.sub = clean(b.sub, 120);
      if ("group" in b) piece.group = clean(b.group, 60) || "Songs";
      if ("yt" in b) {
        const raw = clean(b.yt, 300);
        if (!raw) piece.yt = null;
        else { const y = ytFrom(raw); if (!y) return fail(YT_ERR); piece.yt = y; }
      }
      await writeIndex(env, idx);
      return json(piece);
    }
    if (seg.length === 2 && method === "DELETE") {
      const keys = [piece.score?.key, ...piece.tracks.map((t) => t.key)].filter(Boolean);
      idx.pieces = idx.pieces.filter((p) => p.id !== piece.id);
      await writeIndex(env, idx);
      if (keys.length) await env.BUCKET.delete(keys);
      await deleteAnnotations(env, { pieceId: piece.id });
      return json({ ok: true });
    }

    // score (PDF / PNG / JPG / WebP)
    if (seg[2] === "score" && seg.length === 3) {
      if (method === "PUT") {
        const r = await readBody(request);
        if (r.error) return r.error;
        const kind = sniffScore(head(r.buf));
        if (!kind) return fail("Score must be a PDF, PNG, JPG or WebP file");
        const key = `pieces/${piece.id}/score-${Date.now()}.${kind.type}`;
        await env.BUCKET.put(key, r.buf, { httpMetadata: { contentType: kind.mime, cacheControl: CACHE } });
        const old = piece.score?.key;
        piece.score = { key, type: kind.type, name: clean(url.searchParams.get("name"), 120) || `score.${kind.type}`, size: r.buf.byteLength };
        await writeIndex(env, idx);
        if (old) await env.BUCKET.delete(old);
        return json(piece);
      }
      if (method === "DELETE") {
        const old = piece.score?.key;
        piece.score = null;
        await writeIndex(env, idx);
        if (old) await env.BUCKET.delete(old);
        return json(piece);
      }
    }

    // MP3 practice tracks
    if (seg[2] === "tracks") {
      if (seg.length === 3 && method === "POST") {
        if (piece.tracks.length >= MAX_TRACKS) return fail(`A piece can have up to ${MAX_TRACKS} tracks`);
        // YouTube-only track (JSON body, no MP3)
        if ((request.headers.get("content-type") || "").includes("application/json")) {
          const b = await request.json().catch(() => ({}));
          const y = ytFrom(b.yt);
          if (!y) return fail(YT_ERR);
          piece.tracks.push({
            id: newId(), key: null, voice: VOICES.includes(b.voice) ? b.voice : "Other",
            name: clean(b.name, 60) || "YouTube guide", size: 0, yt: y,
          });
          await writeIndex(env, idx);
          return json(piece);
        }
        const ytRaw = url.searchParams.get("yt");
        if (ytRaw && !ytFrom(ytRaw)) return fail(YT_ERR);
        const r = await readBody(request);
        if (r.error) return r.error;
        if (!isMp3(head(r.buf))) return fail("Tracks must be MP3 files");
        const v = url.searchParams.get("voice");
        const tid = newId();
        const key = `pieces/${piece.id}/tracks/${tid}.mp3`;
        await env.BUCKET.put(key, r.buf, { httpMetadata: { contentType: "audio/mpeg", cacheControl: CACHE } });
        piece.tracks.push({
          id: tid, key, voice: VOICES.includes(v) ? v : "Other",
          name: clean(url.searchParams.get("name"), 60) || "Track", size: r.buf.byteLength, yt: ytFrom(url.searchParams.get("yt")),
        });
        await writeIndex(env, idx);
        return json(piece);
      }
      if (seg.length === 4) {
        const t = piece.tracks.find((x) => x.id === seg[3]);
        if (!t) return fail("Track not found", 404);
        if (method === "PATCH") {
          const b = await request.json().catch(() => ({}));
          if (VOICES.includes(b.voice)) t.voice = b.voice;
          if ("name" in b) t.name = clean(b.name, 60) || t.name;
          if ("yt" in b) {
            const raw = clean(b.yt, 300);
            if (!raw) {
              if (!t.key) return fail("A YouTube-only track needs its link. Delete the track instead.");
              t.yt = null;
            } else { const y = ytFrom(raw); if (!y) return fail(YT_ERR); t.yt = y; }
          }
          await writeIndex(env, idx);
          return json(piece);
        }
        if (method === "DELETE") {
          piece.tracks = piece.tracks.filter((x) => x.id !== t.id);
          await writeIndex(env, idx);
          if (t.key) await env.BUCKET.delete(t.key);
          return json(piece);
        }
      }
    }

    return fail("Not found", 404);
  } catch (e) {
    return fail(e.message || "Server error", 500);
  }
}

